// ═══════════════════════════════════════════════════════════════════
// 电影大师 · 缺 <imgthink> 自动补全（酒馆助手脚本 v1.1）
// 触发：只有点按钮「修复本条」才检测（自动补默认关闭）→ 扫最新一楼
// 判定：每个 <image>…</image> 前面必须紧贴 </imgthink>
// 处理：用 AI 补一个 think + 重写该 image（180-200 token），原地替换文本
// 手动：点「修复本条」→ 先判断要不要补，不补就提示
// 提示：生成后只检测，缺 think 时按钮文字变「需修复」，补好后自动变回
// ═══════════════════════════════════════════════════════════════════

const CFG = {
  auto: false,       // false=只靠按钮触发（默认）；true=生成后自动检查
  dryRun: false,     // true=只打印，不改消息（先试跑用）
  maxRepair: 4,      // 单条消息最多补几处，防死循环
  historyChars: 1200 // 修复时附带的最近正文长度
};

const TH = (typeof TavernHelper !== 'undefined' && TavernHelper) || globalThis;
const getMsgs = TH.getChatMessages || globalThis.getChatMessages;
const setMsgs = TH.setChatMessages || globalThis.setChatMessages;
const onEvent = TH.eventOn || globalThis.eventOn;
const EVENTS  = TH.tavern_events || globalThis.tavern_events || {};
const genRaw  = TH.generateRaw || globalThis.generateRaw;
const gen     = TH.generate || globalThis.generate;
const toast   = TH.toastr || globalThis.toastr;

const log = (...a) => console.log('[FM-pair]', ...a);
const seen = new Set();

// ── 按钮文字：需修复 / 修复本条 ──────────────────────────────────
let needFix = false;
let btnEl = null;

function docRef() {
  try { if (typeof window !== 'undefined' && window.parent && window.parent.document) return window.parent.document; } catch (e) {}
  try { if (typeof document !== 'undefined') return document; } catch (e) {}
  return null;
}

function findFixButton(doc) {
  if (!doc || !doc.querySelectorAll) return null;
  const list = doc.querySelectorAll('button, .menu_button, [role="button"]');
  for (const b of list) {
    const t = (b.textContent || '').trim();
    if (t === '修复本条' || t === '需修复') return b;
  }
  return null;
}

// 和「图片归位」同用时：把自己挪到「正文标签」输入框左边
function arrangeBesideTagBox(doc, btn) {
  try {
    if (!doc || !doc.getElementById || !btn || !btn.parentNode) return;
    const box = doc.getElementById('fm-move-tag');
    if (!box || !box.parentNode) return;
    if (btn.parentNode === box.parentNode && btn.nextSibling === box) return;  // 已就位
    box.parentNode.insertBefore(btn, box);
    if (!btn.style || !btn.style.marginRight) { try { btn.style.marginRight = '6px'; } catch (e) {} }
    log('已把「' + ((btn.textContent || '').trim()) + '」摆到正文标签框左边');
  } catch (e) { log('摆放按钮失败', e); }
}

// 只改显示文字，不动按钮名（事件仍绑在「修复本条」上）
function paintLabel() {
  const want = needFix ? '需修复' : '修复本条';
  const doc = docRef();
  if (!doc) return;
  let el = btnEl;
  try {
    if (!el || (typeof doc.contains === 'function' && !doc.contains(el))) el = findFixButton(doc);
  } catch (e) { el = findFixButton(doc); }
  if (!el) { el = findFixButton(doc); }
  if (!el) return;
  btnEl = el;
  if ((el.textContent || '').trim() !== want) el.textContent = want;
  arrangeBesideTagBox(doc, el);
}

if (docRef()) setInterval(paintLabel, 1200);

// 只检测、不修复：决定按钮显示哪个字
async function detect(id) {
  try {
    const got = await getMsgs(id);
    const msg = (got || [])[0];
    if (!msg || msg.role !== 'assistant') return;
    const n = findOrphans(msg.message || '').length;
    const before = needFix;
    needFix = n > 0;
    if (before !== needFix) log(needFix ? '检测到 ' + n + ' 处缺 think → 按钮改为「需修复」' : '本条已配对 → 按钮复位「修复本条」');
    paintLabel();
    return needFix;
  } catch (e) { log('检测失败', e); return false; }
}

// ── 送进模型的修复提示词 ──────────────────────────────────────────
function buildPrompt(block, ctx) {
  return `你是「电影大师」提示词格式修复器。下面这条回复里有一个 <image> 缺少紧邻的 <imgthink>。
请**只输出**一对标签，不要解释、不要代码块、不要多余文字：

<imgthink>
[S1 上下文视觉要点] 提炼正文里的视觉信息（服装/姿势/身体状态/位置/体液），40-150字，禁止复制原文
[S2 分级] 依据穿着判断 Safe / R / X 并说明依据
[S3 交互防反转] 指出动作的主语
[S4 多角色处理] 人数、人数词、空间位置；单人写"单人场景，跳过"
[S5 镜头语言] 景别 / 视角 / 构图
[S6 装填指引] 从角色DNA里摘哪几类标签（只指引，不装填）
[S6.5 年龄控制] 中年角色逐项检查；无则写"非中年，免检"
[S7 最终审计] 逐项写：人数词 / 服装颜色 / 肤色 / 权重保留 / 分级 是否通过
</imgthink>
<image>【沿用原标题】
image###Scene Composition:…;Character 1 Prompt:…;Character 1 UC:…;…###
</image>

硬性要求：
1. 改写后的正向部分（Scene + 全部 Character Prompt，不含 UC）180-200 token；
   { } [ ] ( ) :: :1.8 , 这些符号计入，UC 不计入。
2. 人数词：1人 solo ｜ 2人 {duo},{2people} ｜ 3人 {trio},2girls,1boy ｜
   4人 {group},3girls,1boy ｜ 5人 {group},4girls,1boy。
3. 角色名一律拼音（如 Su Wanqing），禁止中文汉字；每角色 (名:1.6~1.8)。
4. 3人及以上：不写 -1.5::…::（改在 UC 写 1.5::对方发色::）；只有发色用 {{}}，其余单 {}。
5. 每角色保留：性别标签、名、{{发色}}、服装、动作、表情、位置。
6. 每一步都要写实质内容，禁止"同上 / 略 / 全✓"。

【最近正文】
${ctx}

【违规的 image 原文】
${block}`;
}

// ── 找缺 think 的 image 块 ───────────────────────────────────────
function findOrphans(msg) {
  const out = [];
  const re = /<image[^>]*>[\s\S]*?<\/image>/g;
  let m;
  while ((m = re.exec(msg)) !== null) {
    const before = msg.slice(0, m.index).replace(/[\s　]+$/, '');
    if (!before.endsWith('</imgthink>')) out.push({ start: m.index, end: m.index + m[0].length, block: m[0] });
  }
  return out;
}

// 有 <imgthink> 没闭合时，把残片一起清掉
function trimOpenThink(msg, cut) {
  const head = msg.slice(0, cut);
  const open = head.lastIndexOf('<imgthink>');
  const close = head.lastIndexOf('</imgthink>');
  if (open > close) return { head: head.slice(0, open), drop: cut - open };
  return { head, drop: 0 };
}

// ── 调模型 ──────────────────────────────────────────────────────
async function aiFix(prompt) {
  if (typeof genRaw === 'function') {
    try { const r = await genRaw({ user_input: prompt, should_silence: true }); if (r) return r; }
    catch (e) { log('generateRaw 失败', e); }
  }
  if (typeof gen === 'function') {
    try { const r = await gen({ user_input: prompt, should_silence: true }); if (r) return r; }
    catch (e) { log('generate(should_silence) 失败', e); }
    try { const r = await gen({ user_input: prompt }); if (r) return r; }
    catch (e) { log('generate 失败', e); }
  }
  return '';
}

function pickPair(text) {
  const t = String(text || '');
  const th = t.match(/<imgthink>[\s\S]*?<\/imgthink>/i);
  const im = t.match(/<image[^>]*>[\s\S]*?<\/image>/i);
  return th && im ? th[0].trim() + '\n' + im[0].trim() : null;
}

// 没有可用的生成接口时兜底：只补骨架，保证配对
function skeleton(block) {
  const inner = block.replace(/^<image[^>]*>/, '').replace(/<\/image>$/, '').replace(/image###|###/g, ' ').trim();
  return '<imgthink>\n'
    + '[S1] 视觉要点：' + inner.slice(0, 100) + '…\n'
    + '[S2] 分级见 UC ｜ [S3] 动作已绑主语 ｜ [S4] 人数词见 Scene\n'
    + '[S5] 景别见 Scene ｜ [S6] 取自角色DNA ｜ [S6.5] 非中年 ｜ [S7] 待人工确认\n'
    + '</imgthink>\n' + block;
}

// ── 主修复 ──────────────────────────────────────────────────────
async function repairMessage(messageId) {
  let got;
  try { got = await getMsgs(messageId); } catch (e) { return log('getChatMessages 不可用', e); }
  const msg = (got || [])[0];
  if (!msg || msg.role !== 'assistant') return { n: 0, why: '最新一楼不是 AI 回复' };
  const text = msg.message || '';
  const orphans = findOrphans(text);
  if (!orphans.length) return { n: 0, why: '图片都已配对，无需补' };

  log('发现缺 think 的 image：', orphans.length, '处');
  const jobs = orphans.slice(0, CFG.maxRepair);
  const patches = [];

  for (const o of jobs) {
    const ctx = text.slice(Math.max(0, o.start - CFG.historyChars), o.start);
    let pair = null;
    if (typeof genRaw === 'function' || typeof gen === 'function') {
      pair = pickPair(await aiFix(buildPrompt(o.block, ctx)));
    }
    if (!pair) { log('AI 未返回可用结果，用骨架兜底'); pair = skeleton(o.block); }
    patches.push({ block: o.block, start: o.start, end: o.end, pair });
  }

  if (!patches.length) return;

  // 写回前重新读一次：图片归位脚本可能刚把图挪过位置
  let latest = text;
  try {
    const g2 = await getMsgs(messageId);
    if (g2 && g2[0] && typeof g2[0].message === 'string') latest = g2[0].message;
  } catch (e) { log('复查消息失败，按原文本写回', e); }
  if (latest !== text) log('文本已被其他脚本改动，按新文本重新定位', messageId);

  // 用 image 块原文在新文本里重新定位（块内容没变，只是位置变了）
  let cursor = 0;
  const located = [];
  for (const p of patches) {
    let idx = latest.indexOf(p.block, cursor);
    if (idx < 0) idx = latest.indexOf(p.block);
    if (idx < 0) { log('定位失败，跳过一处：', p.block.slice(0, 40)); continue; }
    cursor = idx + p.block.length;
    located.push({ start: idx, end: idx + p.block.length, pair: p.pair });
  }
  if (!located.length) return { n: 0, why: '没有可写回的位置' };

  let out = latest;
  for (let i = located.length - 1; i >= 0; i--) {
    const p = located[i];
    const head = out.slice(0, p.start);
    const open = head.lastIndexOf('<imgthink>');
    const close = head.lastIndexOf('</imgthink>');
    const from = open > close ? open : p.start;   // 残缺 think 一并清掉
    out = out.slice(0, from) + p.pair + out.slice(p.end);
  }

  if (CFG.dryRun) { log('dryRun 预览：\n' + out.slice(0, 800)); return { n: 0, why: 'dryRun 已打印' }; }
  try {
    await setMsgs([{ message_id: messageId, message: out }]);
    log('已修复', messageId, '补', patches.length, '处');
    return { n: located.length, why: '已补齐 ' + located.length + ' 处' };
  } catch (e) { log('setChatMessages 失败', e); return { n: 0, why: '写回失败：' + e }; }
}

// ── 事件 ────────────────────────────────────────────────────────
async function lastId() {
  try {
    if (typeof TH.getLastMessageId === 'function') {
      const id = await TH.getLastMessageId();
      if (id !== null && id !== undefined) return id;
    }
  } catch (e) {}
  try {
    if (typeof getMsgs === 'function') {
      const l = await getMsgs(-1);
      if (l && l.length) return l[l.length - 1].message_id;
    }
  } catch (e) {}
  return null;
}

if (typeof onEvent === 'function') {
  // 生成完只做一次本地检测（不调模型、不改消息），决定按钮显示「需修复」
  onEvent(EVENTS.MESSAGE_RECEIVED || 'message_received', (id) => { detect(id); });
  ['MESSAGE_EDITED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED'].forEach(k => {
    const name = EVENTS[k];
    if (!name) return;
    try { onEvent(name, (id) => { if (id !== null && id !== undefined) detect(id); }); } catch (e) {}
  });
  try {
    onEvent(EVENTS.CHAT_CHANGED || 'chat_changed', () => {
      needFix = false; paintLabel();
      lastId().then(id => { if (id !== null && id !== undefined) detect(id); });
    });
  } catch (e) {}

  if (CFG.auto) {
    onEvent(EVENTS.MESSAGE_RECEIVED || 'message_received', async (id) => {
      if (seen.has(id)) return;
      seen.add(id);
      try { await repairMessage(id); } catch (e) { log('自动修复异常', e); }
    });
    log('已挂载 MESSAGE_RECEIVED 自动修复');
  } else {
    log('自动补已关闭：只在点「修复本条」时检测');
  }

  const getButtonEvent = TH.getButtonEvent || globalThis.getButtonEvent;
  if (typeof getButtonEvent === 'function') {
    const ev = getButtonEvent('修复本条');
    if (!ev) log('⚠️ 没拿到「修复本条」的按钮事件');
    ev && onEvent(ev, async () => {
      log('按钮点击：修复本条');
      try {
        const id = await lastId();
        if (id === null || id === undefined) {
          toast && toast.error && toast.error('补 imgthink：找不到最新楼层');
          return;
        }
        seen.delete(id);
        log('检测楼层：', id);
        const r = await repairMessage(id);
        log('按钮结果：', r);
        if (r && r.n > 0) {
          needFix = false;                       // 修好了 → 按钮变回「修复本条」
          paintLabel();
          toast && toast.success && toast.success('已补齐 imgthink：' + r.n + ' 处');
        } else {
          const f = (toast && (toast.info || toast.warning || toast.success)) || null;
          f && f('补 imgthink：' + ((r && r.why) || '无需补'));
        }
      } catch (e) {
        log('按钮修复异常', e);
        toast && toast.error && toast.error('补 imgthink 异常：' + e);
      }
    });
  }
}

globalThis.FM_pair = { repairMessage, findOrphans, detect, paintLabel, arrangeBesideTagBox, CFG, get needFix(){ return needFix; } };
log('电影大师补imgthink 加载完成', CFG);
